def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get_pos(keys):
        for k in keys:
            v = observation.get(k)
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        me = observation.get("self", {})
        if isinstance(me, dict):
            for k in ("pos", "position", "loc", "location"):
                v = me.get(k)
                if isinstance(v, (list, tuple)) and len(v) >= 2:
                    return int(v[0]), int(v[1])
        return None

    def is_pair(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float))

    def extract_positions(obj):
        out = []
        if obj is None:
            return out
        if is_pair(obj):
            out.append((int(obj[0]), int(obj[1])))
            return out
        if isinstance(obj, dict):
            for k in ("positions", "pos", "position", "cells", "targets", "items", "resources", "enemies", "opponents", "agents"):
                if k in obj:
                    out.extend(extract_positions(obj.get(k)))
            return out
        if isinstance(obj, (list, tuple)):
            for it in obj:
                if is_pair(it):
                    out.append((int(it[0]), int(it[1])))
                elif isinstance(it, dict):
                    out.extend(extract_positions(it))
                elif isinstance(it, (list, tuple)):
                    out.extend(extract_positions(it))
        return out

    def nearest(src, pts):
        best = None
        best_d = None
        sx, sy = src
        for x, y in pts:
            d = abs(x - sx) + abs(y - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = (x, y)
        return best, best_d

    me = get_pos(("pos", "position", "agent_pos", "agent_position", "self_pos", "self_position", "loc", "location"))
    if me is None:
        return [0, 0]
    mx, my = me

    resources = []
    for k in ("resources", "resource_positions", "resource_tiles", "targets", "food", "pellets"):
        resources.extend(extract_positions(observation.get(k)))

    enemies = []
    for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "adversaries"):
        enemies.extend(extract_positions(observation.get(k)))

    territory = []
    for k in ("territory", "frontier", "unclaimed", "capture_points", "empty_tiles"):
        territory.extend(extract_positions(observation.get(k)))

    walls = set(extract_positions(observation.get("walls")))  # may be empty
    blocked = set(walls)

    # Parse grid-like map if available
    grid = observation.get("grid")
    if isinstance(grid, (list, tuple)) and grid:
        for y, row in enumerate(grid):
            if isinstance(row, (list, tuple)):
                for x, cell in enumerate(row):
                    if cell in (1, "#", "W", "wall", "blocked", True):
                        blocked.add((x, y))
                    if cell in ("R", "resource", "food", "*"):
                        resources.append((x, y))
                    if cell in ("T", "territory", ".", "empty", 0):
                        territory.append((x, y))
                    if cell in ("E", "enemy", "opponent"):
                        enemies.append((x, y))

    # Remove duplicates
    resources = list(dict.fromkeys(resources))
    enemies = list(dict.fromkeys(enemies))
    territory = list(dict.fromkeys(territory))

    # Threat avoidance
    danger_dx = 0
    danger_dy = 0
    threat_found = False
    for ex, ey in enemies:
        d = abs(ex - mx) + abs(ey - my)
        if d <= 2:
            threat_found = True
            danger_dx += clamp_step(mx - ex) * (3 - d)
            danger_dy += clamp_step(my - ey) * (3 - d)

    # Prefer resource if present, else territory, else chase/avoid depending on mode
    target = None
    td = None
    if resources:
        target, td = nearest((mx, my), resources)
    elif territory:
        target, td = nearest((mx, my), territory)
    elif enemies:
        target, td = nearest((mx, my), enemies)

    # If threatened and not very close to a resource, evade
    if threat_found and (not resources or (td is not None and td > 2)):
        dx = clamp_step(danger_dx)
        dy = clamp_step(danger_dy)
        if dx == 0 and dy == 0:
            # choose a safe orthogonal step
            candidates = [(1, 0), (-1, 0), (0, 1), (0, -1)]
            best = (0, 0)
            best_score = None
            for cx, cy in candidates:
                nx, ny = mx + cx, my + cy
                if (nx, ny) in blocked:
                    continue
                score = 0
                for ex, ey in enemies:
                    score += abs(nx - ex) + abs(ny - ey)
                if best_score is None or score > best_score:
                    best_score = score
                    best = (cx, cy)
            dx, dy = best
        if (mx + dx, my + dy) in blocked:
            dx, dy = 0, 0
        return [dx, dy]

    if target is not None:
        tx, ty = target
        dx = clamp_step(tx - mx)
        dy = clamp_step(ty - my)

        # Try axis order with obstacle avoidance
        options = []
        if abs(tx - mx) >= abs(ty - my):
            options = [(dx, 0), (0, dy), (dx, dy), (0, 0)]
        else:
            options = [(0, dy), (dx, 0), (dx, dy), (0, 0)]

        for ox, oy in options:
            if (mx + ox, my + oy) not in blocked:
                return [ox, oy]

    # Fallback: move away from nearby enemies, otherwise wander deterministically
    if enemies:
        best = (0, 0)
        best_score = None
        for ox, oy in ((1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)):
            nx, ny = mx + ox, my + oy
            if (nx, ny) in blocked:
                continue
            score = 0
            for ex, ey in enemies:
                score += abs(nx - ex) + abs(ny - ey)
            if best_score is None or score > best_score:
                best_score = score
                best = (ox, oy)
        return [best[0], best[1]]

    # Simple deterministic patrol
    parity = (mx * 31 + my * 17) % 4
    moves = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    for i in range(4):
        ox, oy = moves[(parity + i) % 4]
        if (mx + ox, my + oy) not in blocked:
            return [ox, oy]

    return [0, 0]

